import{_ as a,C as o,o as r,c as n,a3 as t,E as d}from"./chunks/framework.BJ2rlPXv.js";const b=JSON.parse('{"title":"Response View","description":"","frontmatter":{},"headers":[],"relativePath":"tui/response-preview.md","filePath":"tui/response-preview.md","lastUpdated":1795474269000}'),i={name:"tui/response-preview.md"};function c(h,e,l,p,u,m){const s=o("Screen");return r(),n("div",null,[e[0]||(e[0]=t('<h1 id="response-view" tabindex="-1">Response View <a class="header-anchor" href="#response-view" aria-label="Permalink to &quot;Response View&quot;">​</a></h1><p>The editor and the request list show responses in the same view. Both send requests through the same runner as <code>lazyapi run</code>, so they show the same checks.</p><h2 id="status-line" tabindex="-1">Status line <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Status line&quot;">​</a></h2><p><code>200 OK · 41 ms · 1.2 KB · ✓ 3 checks</code>. The badge is colored by status class: green 2xx, blue 3xx, peach 4xx, red 5xx. A request that never got a response shows <code>ERROR</code> and the reason. While a request is in flight, a spinner is shown; <code>esc</code> cancels.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2>',5)),d(s,{name:"list-checks",caption:"The Checks tab: request, status, contract and each test()"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Tab</th><th>Content</th></tr></thead><tbody><tr><td><strong>Body</strong></td><td>Pretty-printed and syntax-highlighted (JSON, YAML, XML, HTML, JS, CSS). JSON keeps key order and is not HTML-escaped. <code>r</code> shows the raw body</td></tr><tr><td><strong>Headers</strong></td><td>The request that was sent (URL, headers with secrets redacted) and the response headers</td></tr><tr><td><strong>Cookies</strong></td><td>Cookies set by the response, with domain, path, expiry, <code>HttpOnly</code>, <code>Secure</code> and <code>SameSite</code></td></tr><tr><td><strong>Timeline</strong></td><td>DNS, TCP connect, TLS handshake, waiting (TTFB) and download, as proportional bars; a reused keep-alive connection is noted</td></tr><tr><td><strong>Checks</strong></td><td><code>status</code> (declared in the spec), <code>contract</code> (body/headers match the schema) and every <code>test()</code> from the script, each with its failure message</td></tr><tr><td><strong>Console</strong></td><td><code>console.log/info/warn/error</code> from the test script</td></tr></tbody></table><p>When a check fails, the view opens on <strong>Checks</strong>.</p><p>In the editor, the script that runs is the one in the Tests tab, including unsaved edits. In the list it is the operation&#39;s saved <code>x-lazyapi-tests</code> script.</p><h2 id="jq-filter" tabindex="-1">jq filter <a class="header-anchor" href="#jq-filter" aria-label="Permalink to &quot;jq filter&quot;">​</a></h2><p><code>f</code> opens a jq filter for the body (<code>.items[] | {id, name}</code>, <code>.data | length</code>, <code>map(select(.active))</code>). <code>enter</code> applies it; the body tab then shows only the filter output, and the filter stays applied when you send the request again. <code>f</code> and an empty <code>enter</code> remove it. Errors (invalid filter, body that is not JSON) are shown in place of the body. Checks always run on the full body.</p><p>The same filter exists for agents and scripts: <code>lazyapi send ... --jq &#39;.id&#39;</code> and the <code>jq</code> argument of the MCP <code>send_request</code> tool.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>With the response focused, <code>/</code> opens a search. <code>enter</code> highlights every match (case-insensitive) and <code>n</code> / <code>N</code> move between them. While a search is active, the content is shown without syntax colors. Search again with an empty query to clear it.</p><h2 id="saving-examples" tabindex="-1">Saving examples <a class="header-anchor" href="#saving-examples" aria-label="Permalink to &quot;Saving examples&quot;">​</a></h2><p><code>ctrl+e</code> saves the last response as an OpenAPI example in the spec (<code>responses.&lt;code&gt;.content.&lt;type&gt;.example</code>).</p>',10))])}const f=a(i,[["render",c]]);export{b as __pageData,f as default};
